1	// Package indexroom implements chain ingestion with reorg handling.
2	package indexroom
3	
4	import (
5		"fmt"
6		"net"
7		"sort"
8		"strconv"
9		"strings"
10		"unicode"
11	)
12	
13	// Instance is one discoverable service instance.
14	type Instance struct {
15		ID      string
16		Address string
17	}
18	
19	// HealthState is the offline health observation of one instance.
20	// Health is driven entirely by submitted observations; no probing occurs.
21	type HealthState string
22	
23	// Health states.
24	const (
25		HealthUnknown   HealthState = "unknown"
26		HealthHealthy   HealthState = "healthy"
27		HealthUnhealthy HealthState = "unhealthy"
28	)
29	
30	// InstanceView is a snapshot of one instance together with its health observation.
31	type InstanceView struct {
32		ID       string
33		Address  string
34		Health   HealthState
35		Sequence int64
36		Reason   string
37	}
38	
39	// Registration is a validated request that replaces a service's instance list.
40	type Registration struct {
41		Service   string
42		Revision  int
43		Instances []Instance
44	}
45	
46	// HealthUpdate is a validated health observation request.
47	type HealthUpdate struct {
48		Service    string
49		InstanceID string
50		Revision   int
51		Sequence   int64
52		Healthy    bool
53		Reason     string
54	}
55	
56	// ServiceView is an immutable snapshot of one registered service.
57	type ServiceView struct {
58		Service   string
59		Revision  int
60		Instances []InstanceView
61	}
62	
63	// OutcomeKind classifies a failed request.
64	type OutcomeKind string
65	
66	// Outcome kinds.
67	const (
68		OutcomeInvalid  OutcomeKind = "invalid"
69		OutcomeConflict OutcomeKind = "conflict"
70		OutcomeNotFound OutcomeKind = "not_found"
71		OutcomeStale    OutcomeKind = "stale"
72	)
73	
74	// Outcome is the result of applying one registration against the registry.
75	type Outcome struct {
76		Service  string
77		OK       bool
78		Changed  bool
79		Revision int
80		Kind     OutcomeKind
81		Reason   string
82		Expected int
83		Actual   int
84	}
85	
86	// HealthOutcome is the result of applying one health update against the registry.
87	type HealthOutcome struct {
88		Service    string
89		InstanceID string
90		OK         bool
91		Changed    bool
92		Kind       OutcomeKind
93		Reason     string
94		Revision   int
95		Expected   int
96		Actual     int
97		Sequence   int64
98	}
99	
100	// Registry is an in-memory service instance registry.
101	type Registry struct {
102		services map[string]*serviceState
103	}
104	
105	type serviceState struct {
106		revision  int
107		instances map[string]*instanceState // instance id -> state
108	}
109	
110	type instanceState struct {
111		address  string
112		health   HealthState
113		sequence int64
114		reason   string
115	}
116	
117	// newInstanceState returns a fresh observation: unknown with sequence 0.
118	func newInstanceState(address string) *instanceState {
119		return &instanceState{address: address, health: HealthUnknown}
120	}
121	
122	// NewRegistry returns an empty registry.
123	func NewRegistry() *Registry {
124		return &Registry{services: map[string]*serviceState{}}
125	}
126	
127	// RevisionOf returns the service's current revision, or 0 when it is unknown.
128	func (r *Registry) RevisionOf(service string) int {
129		if st, ok := r.services[service]; ok {
130			return st.revision
131		}
132		return 0
133	}
134	
135	// ValidateRegistration trims and validates one request without mutating the registry.
136	// Content validity is established before any revision check.
137	func (r *Registry) ValidateRegistration(service string, revision int, instances []Instance) (Registration, error) {
138		name := strings.TrimSpace(service)
139		if name == "" {
140			return Registration{}, errInvalid("service name must not be empty")
141		}
142		if revision < 0 {
143			return Registration{}, errInvalid("expectedRevision must be a non-negative integer")
144		}
145		seen := make(map[string]bool, len(instances))
146		valid := make([]Instance, 0, len(instances))
147		for _, inst := range instances {
148			id := strings.TrimSpace(inst.ID)
149			if id == "" {
150				return Registration{}, errInvalid("instance id must not be empty")
151			}
152			if seen[id] {
153				return Registration{}, errInvalid(fmt.Sprintf("duplicate instance id %q", id))
154			}
155			addr, err := parseAddress(inst.Address)
156			if err != nil {
157				return Registration{}, errInvalid(err.Error())
158			}
159			seen[id] = true
160			valid = append(valid, Instance{ID: id, Address: addr})
161		}
162		return Registration{Service: name, Revision: revision, Instances: valid}, nil
163	}
164	
165	// Apply checks the revision and, on match, replaces the service's instance list.
166	// A new service is created at revision 1 only when expectedRevision is 0.
167	// A matching registration with identical content succeeds without bumping revision.
168	func (r *Registry) Apply(reg Registration) Outcome {
169		st, exists := r.services[reg.Service]
170		if !exists {
171			if reg.Revision != 0 {
172				return Outcome{
173					Service:  reg.Service,
174					OK:       false,
175					Kind:     OutcomeConflict,
176					Reason:   fmt.Sprintf("service %q does not exist yet; expected revision must be 0, got %d", reg.Service, reg.Revision),
177					Expected: reg.Revision,
178					Actual:   0,
179					Revision: 0,
180				}
181			}
182			st = &serviceState{revision: 1, instances: make(map[string]*instanceState, len(reg.Instances))}
183			r.services[reg.Service] = st
184			for _, inst := range reg.Instances {
185				st.instances[inst.ID] = newInstanceState(inst.Address)
186			}
187			return Outcome{Service: reg.Service, OK: true, Changed: true, Revision: 1}
188		}
189		if reg.Revision != st.revision {
190			return Outcome{
191				Service:  reg.Service,
192				OK:       false,
193				Kind:     OutcomeConflict,
194				Reason:   fmt.Sprintf("service %q is at revision %d, not %d", reg.Service, st.revision, reg.Revision),
195				Expected: reg.Revision,
196				Actual:   st.revision,
197				Revision: st.revision,
198			}
199		}
200		changed := !sameInstances(st.instances, reg.Instances)
201		if changed {
202			// A replacement fully rebuilds the list, but an instance that keeps both
203			// its id and its address retains its health observation. Anything new,
204			// address-changed, or removed-then-readded starts from unknown at sequence 0.
205			next := make(map[string]*instanceState, len(reg.Instances))
206			for _, inst := range reg.Instances {
207				if old, ok := st.instances[inst.ID]; ok && old.address == inst.Address {
208					next[inst.ID] = old
209				} else {
210					next[inst.ID] = newInstanceState(inst.Address)
211				}
212			}
213			st.instances = next
214			st.revision++
215		}
216		return Outcome{Service: reg.Service, OK: true, Changed: changed, Revision: st.revision}
217	}
218	
219	// ValidateHealth trims and validates one health observation without mutating
220	// the registry. Content validity is established before any revision check.
221	func (r *Registry) ValidateHealth(service, instanceID string, revision int, sequence int64, healthy bool, reason string) (HealthUpdate, error) {
222		name := strings.TrimSpace(service)
223		if name == "" {
224			return HealthUpdate{}, errInvalid("service name must not be empty")
225		}
226		id := strings.TrimSpace(instanceID)
227		if id == "" {
228			return HealthUpdate{}, errInvalid("instance id must not be empty")
229		}
230		if revision < 0 {
231			return HealthUpdate{}, errInvalid("expectedRevision must be a non-negative integer")
232		}
233		if sequence <= 0 {
234			return HealthUpdate{}, errInvalid("sequence must be a positive integer")
235		}
236		normalizedReason := strings.TrimSpace(reason)
237		if healthy {
238			// A healthy observation carries no reason.
239			normalizedReason = ""
240		} else if normalizedReason == "" {
241			return HealthUpdate{}, errInvalid("reason must not be empty when unhealthy")
242		}
243		return HealthUpdate{
244			Service:    name,
245			InstanceID: id,
246			Revision:   revision,
247			Sequence:   sequence,
248			Healthy:    healthy,
249			Reason:     normalizedReason,
250		}, nil
251	}
252	
253	// ApplyHealth checks the revision and records an offline observation.
254	//
255	// The revision is checked first: a mismatch is a conflict carrying the request
256	// and current revisions, even when the instance exists. With a matching
257	// revision, a missing service or instance is not_found. Sequence handling:
258	//   - a sequence below the accepted one is stale and reports the current sequence;
259	//   - the same sequence with identical normalized status and reason succeeds
260	//     without changing state;
261	//   - the same sequence with different content is a conflict;
262	//   - a newer sequence writes the status and reason.
263	func (r *Registry) ApplyHealth(upd HealthUpdate) HealthOutcome {
264		st, exists := r.services[upd.Service]
265		actual := 0
266		if exists {
267			actual = st.revision
268		}
269		if upd.Revision != actual {
270			return HealthOutcome{
271				Service:  upd.Service,
272				OK:       false,
273				Kind:     OutcomeConflict,
274				Reason:   fmt.Sprintf("service %q is at revision %d, not %d", upd.Service, actual, upd.Revision),
275				Expected: upd.Revision,
276				Actual:   actual,
277				Revision: actual,
278			}
279		}
280		if !exists {
281			return HealthOutcome{
282				Service:  upd.Service,
283				OK:       false,
284				Kind:     OutcomeNotFound,
285				Reason:   fmt.Sprintf("service %q does not exist", upd.Service),
286				Revision: 0,
287			}
288		}
289		cur, ok := st.instances[upd.InstanceID]
290		if !ok {
291			return HealthOutcome{
292				Service:    upd.Service,
293				InstanceID: upd.InstanceID,
294				OK:         false,
295				Kind:       OutcomeNotFound,
296				Reason:     fmt.Sprintf("instance %q does not exist in service %q", upd.InstanceID, upd.Service),
297				Revision:   st.revision,
298			}
299		}
300		if upd.Sequence < cur.sequence {
301			return HealthOutcome{
302				Service:    upd.Service,
303				InstanceID: upd.InstanceID,
304				OK:         false,
305				Kind:       OutcomeStale,
306				Reason:     fmt.Sprintf("sequence %d is older than the current sequence %d", upd.Sequence, cur.sequence),
307				Revision:   st.revision,
308				Sequence:   cur.sequence,
309			}
310		}
311		if upd.Sequence == cur.sequence {
312			want := HealthUnhealthy
313			if upd.Healthy {
314				want = HealthHealthy
315			}
316			if cur.health == want && cur.reason == upd.Reason {
317				return HealthOutcome{
318					Service:    upd.Service,
319					InstanceID: upd.InstanceID,
320					OK:         true,
321					Changed:    false,
322					Revision:   st.revision,
323					Sequence:   cur.sequence,
324				}
325			}
326			return HealthOutcome{
327				Service:    upd.Service,
328				InstanceID: upd.InstanceID,
329				OK:         false,
330				Kind:       OutcomeConflict,
331				Reason:     fmt.Sprintf("sequence %d already used with different health content", upd.Sequence),
332				Revision:   st.revision,
333				Sequence:   cur.sequence,
334			}
335		}
336		// Newer sequence: record the observation. Health updates never bump the
337		// registration revision.
338		if upd.Healthy {
339			cur.health = HealthHealthy
340			cur.reason = ""
341		} else {
342			cur.health = HealthUnhealthy
343			cur.reason = upd.Reason
344		}
345		cur.sequence = upd.Sequence
346		return HealthOutcome{
347			Service:    upd.Service,
348			InstanceID: upd.InstanceID,
349			OK:         true,
350			Changed:    true,
351			Revision:   st.revision,
352			Sequence:   cur.sequence,
353		}
354	}
355	
356	// Snapshot returns all services sorted by name, with instances sorted by id.
357	func (r *Registry) Snapshot() []ServiceView {
358		names := make([]string, 0, len(r.services))
359		for name := range r.services {
360			names = append(names, name)
361		}
362		sort.Strings(names)
363		views := make([]ServiceView, 0, len(names))
364		for _, name := range names {
365			st := r.services[name]
366			ids := make([]string, 0, len(st.instances))
367			for id := range st.instances {
368				ids = append(ids, id)
369			}
370			sort.Strings(ids)
371			instances := make([]InstanceView, 0, len(ids))
372			for _, id := range ids {
373				cur := st.instances[id]
374				instances = append(instances, InstanceView{
375					ID:       id,
376					Address:  cur.address,
377					Health:   cur.health,
378					Sequence: cur.sequence,
379					Reason:   cur.reason,
380				})
381			}
382			views = append(views, ServiceView{Service: name, Revision: st.revision, Instances: instances})
383		}
384		return views
385	}
386	
387	func sameInstances(current map[string]*instanceState, incoming []Instance) bool {
388		if len(current) != len(incoming) {
389			return false
390		}
391		for _, inst := range incoming {
392			if old, ok := current[inst.ID]; !ok || old.address != inst.Address {
393				return false
394			}
395		}
396		return true
397	}
398	
399	// parseAddress validates a host:port address: domains, IPv4 and bracketed IPv6.
400	// No network I/O is performed.
401	func parseAddress(raw string) (string, error) {
402		addr := strings.TrimSpace(raw)
403		if addr == "" {
404			return "", fmt.Errorf("instance address must not be empty")
405		}
406		for _, r := range addr {
407			if unicode.IsSpace(r) || unicode.IsControl(r) {
408				return "", fmt.Errorf("instance address %q must not contain whitespace or control characters", addr)
409			}
410		}
411		host, port, err := net.SplitHostPort(addr)
412		if err != nil {
413			return "", fmt.Errorf("instance address %q is not a host:port address: %v", addr, err)
414		}
415		if host == "" {
416			return "", fmt.Errorf("instance address %q has an empty host", addr)
417		}
418		if !allDigits(port) {
419			return "", fmt.Errorf("instance address %q port %q must be a decimal integer", addr, port)
420		}
421		n, err := strconv.Atoi(port)
422		if err != nil {
423			return "", fmt.Errorf("instance address %q port %q must be a decimal integer", addr, port)
424		}
425		if n < 1 || n > 65535 {
426			return "", fmt.Errorf("instance address %q port %d is out of range (1-65535)", addr, n)
427		}
428		if strings.HasPrefix(addr, "[") {
429			ip := net.ParseIP(host)
430			if ip == nil || !strings.Contains(host, ":") {
431				return "", fmt.Errorf("instance address %q bracketed host is not a valid IPv6 address", addr)
432			}
433		} else if ip := net.ParseIP(host); ip != nil {
434			if ip.To4() == nil {
435				return "", fmt.Errorf("instance address %q IPv6 addresses must be bracketed", addr)
436			}
437		} else if !isDomainName(host) {
438			return "", fmt.Errorf("instance address %q host %q is not a valid domain, IPv4 or bracketed IPv6", addr, host)
439		}
440		return addr, nil
441	}
442	
443	func allDigits(s string) bool {
444		if s == "" {
445			return false
446		}
447		for _, r := range s {
448			if r < '0' || r > '9' {
449				return false
450			}
451		}
452		return true
453	}
454	
455	// isDomainName validates a dotted hostname with alphanumeric/hyphen labels.
456	func isDomainName(host string) bool {
457		if len(host) > 253 {
458			return false
459		}
460		for _, label := range strings.Split(host, ".") {
461			n := len(label)
462			if n == 0 || n > 63 {
463				return false
464			}
465			if label[0] == '-' || label[n-1] == '-' {
466				return false
467			}
468			for _, r := range label {
469				if r == '-' ||
470					(r >= 'a' && r <= 'z') ||
471					(r >= 'A' && r <= 'Z') ||
472					(r >= '0' && r <= '9') {
473					continue
474				}
475				return false
476			}
477		}
478		return true
479	}
480

