10	// runRegisterWith runs runRegister with the given stdin and captured stdout.
11	func runRegisterWith(t *testing.T, input string) (string, int) {
12		t.Helper()
13		oldStdin := os.Stdin
14		oldStdout := os.Stdout
15		defer func() {
16			os.Stdin = oldStdin
17			os.Stdout = oldStdout
18		}()
19		inR, inW, err := os.Pipe()
20		if err != nil {
21			t.Fatalf("pipe: %v", err)
22		}
23		os.Stdin = inR
24		go func() {
25			defer inW.Close()
26			_, _ = inW.WriteString(input)
27		}()
28		outR, outW, err := os.Pipe()
29		if err != nil {
30			t.Fatalf("pipe: %v", err)
31		}
32		os.Stdout = outW
33		code := runRegister()
34		outW.Close()
35		var buf bytes.Buffer
36		if _, err := buf.ReadFrom(outR); err != nil {
37			t.Fatalf("read stdout: %v", err)
38		}
39		return buf.String(), code
40	}
