42	func TestRegisterSuccess(t *testing.T) {
43		input := `{"requests":[
44			{"service":"b","expectedRevision":0,"instances":[{"id":"b2","address":"h2:2"},{"id":"b1","address":"h1:1"}]},
45			{"service":"b","expectedRevision":1,"instances":[{"id":"b1","address":"h1:1"},{"id":"b2","address":"h2:2"}]},
46			{"service":"a","expectedRevision":0,"instances":[]}
47		]}`
48		out, code := runRegisterWith(t, input)
49		if code != 0 {
50			t.Fatalf("exit code: %d, output: %s", code, out)
51		}
52		var got registerOutput
53		if err := json.Unmarshal([]byte(out), &got); err != nil {
54			t.Fatalf("output is not JSON: %v\n%s", err, out)
55		}
56		if len(got.Results) != 3 {
57			t.Fatalf("results: %+v", got.Results)
58		}
59		want := []registerResult{
60			{Service: "b", OK: true, Changed: true, Revision: 1},
61			{Service: "b", OK: true, Changed: false, Revision: 1},
62			{Service: "a", OK: true, Changed: true, Revision: 1},
63		}
64		for i := range want {
65			if got.Results[i] != want[i] {
66				t.Fatalf("result %d: got %+v want %+v", i, got.Results[i], want[i])
67			}
68		}
69		// Services sorted by name; instances sorted by id; empty list kept.
70		if len(got.Services) != 2 {
71			t.Fatalf("services: %+v", got.Services)
72		}
73		if got.Services[0].Service != "a" || got.Services[0].Revision != 1 || len(got.Services[0].Instances) != 0 {
74			t.Fatalf("service a: %+v", got.Services[0])
75		}
76		if got.Services[1].Service != "b" || got.Services[1].Revision != 1 {
77			t.Fatalf("service b: %+v", got.Services[1])
78		}
79		insts := got.Services[1].Instances
80		if len(insts) != 2 || insts[0].ID != "b1" || insts[0].Address != "h1:1" || insts[1].ID != "b2" {
81			t.Fatalf("service b instances: %+v", insts)
82		}
83	}
