85	func TestRegisterFailuresDoNotAbort(t *testing.T) {
86		input := `{"requests":[
87			{"service":"a","expectedRevision":0,"instances":[{"id":"x","address":"h:1"}]},
88			{"service":"a","expectedRevision":5,"instances":[{"id":"y","address":"h:2"}]},
89			{"service":"a","expectedRevision":1,"instances":[{"id":"y","address":"h:2"}]},
90			{"service":"a","expectedRevision":2,"instances":[{"id":"","address":"h:1"}]},
91			{"service":"a","expectedRevision":2,"instances":[{"id":"z","address":"nope"}]},
92			{"service":"b","expectedRevision":1,"instances":[]}
93		]}`
94		out, code := runRegisterWith(t, input)
95		if code != 1 {
96			t.Fatalf("exit code: %d", code)
97		}
98		var got registerOutput
99		if err := json.Unmarshal([]byte(out), &got); err != nil {
100			t.Fatalf("output is not JSON: %v\n%s", err, out)
101		}
102		if len(got.Results) != 6 {
103			t.Fatalf("results: %+v", got.Results)
104		}
105		// 0: create
106		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
107			t.Fatalf("result 0: %+v", r)
108		}
109		// 1: conflict, expected 5 actual 1
110		if r := got.Results[1]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 5 || r.ActualRevision != 1 || r.Revision != 1 {
111			t.Fatalf("result 1: %+v", r)
112		}
113		// 2: update to rev 2
114		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 2 {
115			t.Fatalf("result 2: %+v", r)
116		}
117		// 3: invalid content with a matching revision: still invalid, list untouched
118		if r := got.Results[3]; r.OK || r.Error != "invalid" || r.Revision != 2 {
119			t.Fatalf("result 3: %+v", r)
120		}
121		// 4: invalid address
122		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 2 {
123			t.Fatalf("result 4: %+v", r)
124		}
125		// 5: conflict on a brand-new service
126		if r := got.Results[5]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 1 || r.ActualRevision != 0 || r.Revision != 0 {
127			t.Fatalf("result 5: %+v", r)
128		}
129		// Only the successful registrations are reflected.
130		if len(got.Services) != 1 || got.Services[0].Service != "a" || got.Services[0].Revision != 2 {
131			t.Fatalf("services: %+v", got.Services)
132		}
133		if len(got.Services[0].Instances) != 1 || got.Services[0].Instances[0].ID != "y" {
134			t.Fatalf("instances: %+v", got.Services[0].Instances)
135		}
136	}
